// AR reminder sequence: escalating touches anchored to Due_Date + REMINDER_DAYS offsets.
// Stops on paid/disputed/opted-out/inactive. Business-hours + daily-cap gated.
// Plain Date math (version-safe, no $DateTime).
const openH = Number($env.BUSINESS_HOURS_START || 9);
const closeH = Number($env.BUSINESS_HOURS_END || 19);
if (!($now.hour >= openH && $now.hour < closeH)) return []; // quiet/business-hours gate
const offsets = (($env.REMINDER_DAYS || '0,3,7,14').split(',')).map(n => Number(n.trim())).filter(n => !isNaN(n));
const channels = (($env.REMINDER_CHANNELS || 'sms,email,sms,email').split(',')).map(s => s.trim().toLowerCase());
const maxSteps = offsets.length;
const dailyCap = Number($env.DAILY_CAP || 200);
const biz = $env.BUSINESS_NAME || 'us';
const lateFee = ($env.LATE_FEE_TEXT || '').trim();
const nowMs = $now.toMillis();
const today = $now.toISODate();
const yes = v => String(v || '').toLowerCase() === 'yes';
const dateOf = v => { const t = new Date(v).getTime(); return isNaN(t) ? '' : new Date(t).toISOString().slice(0,10); };
const rows = $input.all().map(i => i.json);
const sentToday = rows.filter(r => r.Last_Outbound_At && dateOf(r.Last_Outbound_At) === today).length;
let remaining = Math.max(0, dailyCap - sentToday);
const terminal = s => ['paid','disputed','opted out','written off','cancelled','complete'].some(t => s.includes(t));
const out = [];
for (const r of rows) {
  if (remaining <= 0) break;
  if (yes(r.Opted_Out)) continue;
  if (yes(r.Disputed)) continue;
  if (String(r.Sequence_Active || 'No').toLowerCase() !== 'yes') continue;
  if (terminal(String(r.Status || '').toLowerCase())) continue;
  if (Number(r.Balance || 0) <= 0) continue;
  const step = Number(r.Reminder_Step || 0);
  if (step >= maxSteps) continue;
  const due = r.Next_Reminder_At ? nowMs >= new Date(r.Next_Reminder_At).getTime() : false;
  if (!due) continue;
  const nextStep = step + 1;
  const isLast = nextStep >= maxSteps;
  const channel = channels[step] || 'sms';
  const first = r.Customer_Name ? (' ' + String(r.Customer_Name).split(' ')[0]) : '';
  const inv = r.Invoice_Number ? ` #${r.Invoice_Number}` : '';
  const bal = r.Balance ? `$${r.Balance}` : 'your balance';
  const dueStr = r.Due_Date ? dateOf(r.Due_Date) : '';
  const link = r.Pay_Link ? ` Pay securely: ${r.Pay_Link}` : ' Reply here and we can help you settle it.';
  const feeNote = lateFee ? ` ${lateFee}` : '';
  // Escalating-but-respectful tone by step index.
  let sms;
  if (step === 0) sms = `Hi${first}, a friendly reminder from ${biz}: invoice${inv} for ${bal}${dueStr ? ' (due ' + dueStr + ')' : ''} is ready to pay.${link}`;
  else if (step === 1) sms = `Hi${first}, just following up from ${biz} on invoice${inv} for ${bal}. It looks unpaid — happy to help if you have questions.${link}`;
  else if (isLast) sms = `Hi${first}, final reminder from ${biz} on the past-due invoice${inv} for ${bal}.${feeNote} Please arrange payment or reply so we can sort it out.${link}`;
  else sms = `Hi${first}, invoice${inv} for ${bal} is now past due. We'd appreciate prompt payment.${feeNote}${link}`;
  sms = `${sms} Reply STOP to opt out.`;
  const emailSubject = step === 0 ? `Invoice${inv} from ${biz}` : (isLast ? `Final reminder: invoice${inv} past due` : `Reminder: invoice${inv} from ${biz}`);
  const emailBody = `Hi${first},\n\n${step === 0 ? 'This is a friendly reminder' : (isLast ? 'This is a final reminder' : 'This is a follow-up reminder')} regarding invoice${inv} for ${bal}${dueStr ? ', due ' + dueStr : ''}.${feeNote}\n\n${r.Pay_Link ? 'You can pay securely here: ' + r.Pay_Link : 'Please reply to arrange payment.'}\n\nIf you've already paid, thank you — please disregard. Questions? Just reply.\n\n— ${biz}\n\nReply STOP to opt out.`;
  let nextAt = '';
  if (!isLast) {
    const dueMs = r.Due_Date ? new Date(r.Due_Date).getTime() : NaN;
    nextAt = isNaN(dueMs) ? $now.plus({ minutes: ((offsets[nextStep] || 0) - (offsets[step] || 0)) * 1440 }).toISO() : new Date(dueMs + (offsets[nextStep] || 0) * 86400000).toISOString();
  }
  out.push({ json: { ...r, _channel: (channel === 'email' && r.Customer_Email) ? 'email' : 'sms', _sms_msg: sms, _email_subject: emailSubject, _email_body: emailBody, _next_step: nextStep, _is_last: isLast, _next_reminder_at: nextAt, _new_status: isLast ? 'Final Reminder Sent' : (step === 0 ? 'Reminder Sent' : 'Past Due - Reminder Sent') } });
  remaining--;
}
return out;
